function switchTab(tab) {
            ['compound', 'emergency', 'cagr', 'emi'].forEach(t => {
                const mod = document.getElementById('module-' + t);
                const btn = document.getElementById('tab-btn-' + t);
                if (t === tab) {
                    mod.classList.remove('hidden');
                    btn.className = 'px-4 py-2.5 rounded-xl font-bold text-xs uppercase tracking-wider transition-all bg-white text-slate-900 shadow-sm border border-slate-200';
                } else {
                    mod.classList.add('hidden');
                    btn.className = 'px-4 py-2.5 rounded-xl font-bold text-xs uppercase tracking-wider transition-all text-slate-500 hover:text-slate-800 hover:bg-white/60';
                }
            });
        }

        const fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

        function calcCompound() {
            const P = parseFloat(document.getElementById('ci-principal').value) || 0;
            const PMT = parseFloat(document.getElementById('ci-monthly').value) || 0;
            const r = (parseFloat(document.getElementById('ci-rate').value) || 0) / 100;
            const t = parseFloat(document.getElementById('ci-years').value) || 0;
            const n = 12;

            const totalMonths = t * 12;
            const monthlyRate = r / 12;
            let balance = P;
            for (let i = 0; i < totalMonths; i++) {
                balance = balance * (1 + monthlyRate) + PMT;
            }
            const totalInvested = P + (PMT * totalMonths);
            const totalInterest = Math.max(0, balance - totalInvested);

            document.getElementById('ci-out-invested').innerText = fmt.format(totalInvested);
            document.getElementById('ci-out-interest').innerText = fmt.format(totalInterest);
            document.getElementById('ci-out-total').innerText = fmt.format(balance);
        }

        function calcEmergency() {
            const exp = parseFloat(document.getElementById('em-expenses').value) || 0;
            const sav = parseFloat(document.getElementById('em-savings').value) || 0;
            const tgtMonths = parseFloat(document.getElementById('em-target-months').value) || 6;

            const runway = exp > 0 ? (sav / exp).toFixed(1) : '0.0';
            const targetFund = exp * tgtMonths;
            const gap = Math.max(0, targetFund - sav);

            document.getElementById('em-out-runway').innerText = runway + ' Months';
            document.getElementById('em-out-target').innerText = fmt.format(targetFund);
            document.getElementById('em-out-gap').innerText = gap > 0 ? fmt.format(gap) : 'Funded!';
        }

        function calcCAGR() {
            const start = parseFloat(document.getElementById('cagr-start').value) || 1;
            const end = parseFloat(document.getElementById('cagr-end').value) || 1;
            const years = parseFloat(document.getElementById('cagr-years').value) || 1;
            const inf = (parseFloat(document.getElementById('cagr-inflation').value) || 0) / 100;

            const nominalCAGR = Math.pow(end / start, 1 / years) - 1;
            const realCAGR = ((1 + nominalCAGR) / (1 + inf)) - 1;
            const multiple = end / start;

            document.getElementById('cagr-out-nominal').innerText = (nominalCAGR * 100).toFixed(1) + '%';
            document.getElementById('cagr-out-real').innerText = (realCAGR * 100).toFixed(1) + '%';
            document.getElementById('cagr-out-multiple').innerText = multiple.toFixed(2) + 'x';
        }

        function calcEMI() {
            const P = parseFloat(document.getElementById('emi-principal').value) || 0;
            const annualRate = (parseFloat(document.getElementById('emi-rate').value) || 0) / 100;
            const years = parseFloat(document.getElementById('emi-tenure').value) || 1;

            const n = years * 12;
            const r = annualRate / 12;
            let emi = 0;
            if (r > 0) {
                emi = P * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1);
            } else {
                emi = P / n;
            }
            const totalRepayment = emi * n;
            const totalInterest = Math.max(0, totalRepayment - P);

            document.getElementById('emi-out-monthly').innerText = fmt.format(emi);
            document.getElementById('emi-out-interest').innerText = fmt.format(totalInterest);
            document.getElementById('emi-out-total').innerText = fmt.format(totalRepayment);
        }

        calcCompound();
        calcEmergency();
        calcCAGR();
        calcEMI();
